/// franka_msgs/msg/Errors. Libfranka error flags exposed by the ROS 2 state translation.
#[derive(Clone, Copy, Default)]
pub struct Errors {
    /// True if the robot moved past the joint limits.
    pub joint_position_limits_violation: bool,
    /// True if the robot moved past any of the virtual walls.
    pub cartesian_position_limits_violation: bool,
    /// True if the robot would have collided with itself.
    pub self_collision_avoidance_violation: bool,
    /// True if the robot exceeded joint velocity limits.
    pub joint_velocity_violation: bool,
    /// True if the robot exceeded Cartesian velocity limits.
    pub cartesian_velocity_violation: bool,
    /// True if the robot exceeded safety threshold during force control.
    pub force_control_safety_violation: bool,
    /// True if a collision was detected, i.e. the robot exceeded a torque threshold in a joint
    /// motion.
    pub joint_reflex: bool,
    /// True if a collision was detected, i.e. the robot exceeded a torque threshold in a Cartesian
    /// motion.
    pub cartesian_reflex: bool,
    /// True if internal motion generator did not reach the goal pose.
    pub max_goal_pose_deviation_violation: bool,
    /// True if internal motion generator deviated from the path.
    pub max_path_pose_deviation_violation: bool,
    /// True if Cartesian velocity profile for internal motions was exceeded.
    pub cartesian_velocity_profile_safety_violation: bool,
    /// True if an external joint position motion generator was started with a pose too far from the
    /// current pose.
    pub joint_position_motion_generator_start_pose_invalid: bool,
    /// True if an external joint motion generator would move into a joint limit.
    pub joint_motion_generator_position_limits_violation: bool,
    /// True if an external joint motion generator exceeded velocity limits.
    pub joint_motion_generator_velocity_limits_violation: bool,
    /// True if commanded velocity in joint motion generators is discontinuous (target values are
    /// too far apart).
    pub joint_motion_generator_velocity_discontinuity: bool,
    /// True if commanded acceleration in joint motion generators is discontinuous (target values
    /// are too far apart).
    pub joint_motion_generator_acceleration_discontinuity: bool,
    /// True if an external Cartesian position motion generator was started with a pose too far from
    /// the current pose.
    pub cartesian_position_motion_generator_start_pose_invalid: bool,
    /// True if an external Cartesian motion generator would move into an elbow limit.
    pub cartesian_motion_generator_elbow_limit_violation: bool,
    /// True if an external Cartesian motion generator would move with too high velocity.
    pub cartesian_motion_generator_velocity_limits_violation: bool,
    /// True if commanded velocity in Cartesian motion generators is discontinuous (target values
    /// are too far apart).
    pub cartesian_motion_generator_velocity_discontinuity: bool,
    /// True if commanded acceleration in Cartesian motion generators is discontinuous (target
    /// values are too far apart).
    pub cartesian_motion_generator_acceleration_discontinuity: bool,
    /// True if commanded elbow values in Cartesian motion generators are inconsistent.
    pub cartesian_motion_generator_elbow_sign_inconsistent: bool,
    /// True if the first elbow value in Cartesian motion generators is too far from initial one.
    pub cartesian_motion_generator_start_elbow_invalid: bool,
    /// True if the joint position limits would be exceeded after IK calculation.
    pub cartesian_motion_generator_joint_position_limits_violation: bool,
    /// True if the joint velocity limits would be exceeded after IK calculation.
    pub cartesian_motion_generator_joint_velocity_limits_violation: bool,
    /// True if the joint velocity in Cartesian motion generators is discontinuous after IK
    /// calculation.
    pub cartesian_motion_generator_joint_velocity_discontinuity: bool,
    /// True if the joint acceleration in Cartesian motion generators is discontinuous after IK
    /// calculation.
    pub cartesian_motion_generator_joint_acceleration_discontinuity: bool,
    /// True if the Cartesian pose is not a valid transformation matrix.
    pub cartesian_position_motion_generator_invalid_frame: bool,
    /// True if desired force exceeds the safety thresholds.
    pub force_controller_desired_force_tolerance_violation: bool,
    /// True if the torque set by the external controller is discontinuous.
    pub controller_torque_discontinuity: bool,
    /// True if the start elbow sign was inconsistent. Applies only to motions started from Desk.
    pub start_elbow_sign_inconsistent: bool,
    /// True if minimum network communication quality could not be held during a motion.
    pub communication_constraints_violation: bool,
    /// True if commanded values would result in exceeding the power limit.
    pub power_limit_violation: bool,
    /// True if the robot is overloaded for the required motion. Applies only to motions started
    /// from Desk.
    pub joint_p2p_insufficient_torque_for_planning: bool,
    /// True if the measured torque signal is out of the safe range.
    pub tau_j_range_violation: bool,
    /// True if an instability is detected.
    pub instability_detected: bool,
}

